# FIMSFit ----
## Setup ----
# Load the test data
data_big <- FIMSFrame(FIMS::data_big)
fit_with_optimization_big <- FIMS::fit_with_optimization_big
fit_without_optimization_big <- FIMS::fit_without_optimization_big

## IO correctness ----
test_that("`is.FIMSFit()` works with fit with optimization", {
  #' @description Test that `is.FIMSFit(fit_with_optimization_big)` returns TRUE.
  expect_true(
    object = is.FIMSFit(fit_with_optimization_big)
  )

  expected_names <- c(
    "input", "obj", "opt", "max_gradient", "gradient", "report", "sdreport",
    "number_of_parameters", "timing", "version", "model_output"
  )
  #' @description Test a FIMSFit object has the correct slot names.
  expect_equal(
    object = slotNames(fit_with_optimization_big),
    expected = expected_names
  )
})

test_that("`is.FIMSFit()` works with fit without optimization", {
  #' @description Test that `is.FIMSFit(fit_without_optimization_big)` returns TRUE.
  expect_true(
    object = is.FIMSFit(fit_without_optimization_big)
  )

  expected_names <- c(
    "input", "obj", "opt", "max_gradient", "gradient", "report", "sdreport",
    "number_of_parameters", "timing", "version", "model_output"
  )
  #' @description Test a FIMSFit object has the correct slot names.
  expect_equal(
    object = slotNames(fit_without_optimization_big),
    expected = expected_names
  )
})

test_that("FIMSFit accessors and show() work on optimized fits", {
  #' @description Test all FIMSFit accessors and show() to improve branch coverage in fimsfit.R.
  # show() is used by users exploring fitted objects interactively.
  expect_no_error(show(fit_with_optimization_big))

  # Accessors are the public API for slots, so keep checks explicit.
  expect_equal(get_input(fit_with_optimization_big), fit_with_optimization_big@input)
  expect_equal(get_obj(fit_with_optimization_big), fit_with_optimization_big@obj)
  expect_equal(get_opt(fit_with_optimization_big), fit_with_optimization_big@opt)
  expect_equal(get_report(fit_with_optimization_big), fit_with_optimization_big@report)
  expect_equal(get_sdreport(fit_with_optimization_big), fit_with_optimization_big@sdreport)
  expect_equal(get_max_gradient(fit_with_optimization_big), fit_with_optimization_big@max_gradient)
  expect_equal(get_gradient(fit_with_optimization_big), fit_with_optimization_big@gradient)
  expect_equal(
    get_number_of_parameters(fit_with_optimization_big),
    fit_with_optimization_big@number_of_parameters
  )
  expect_equal(get_timing(fit_with_optimization_big), fit_with_optimization_big@timing)
  expect_equal(get_version(fit_with_optimization_big), fit_with_optimization_big@version)
  expect_equal(
    get_model_output(fit_with_optimization_big),
    fit_with_optimization_big@model_output
  )
})

test_that("stored gradient remains available after clear()", {
  #' @description Test get_gradient() remains safe after clear() by reading the stored gradient slot.
  # Save the gradient before clear() to verify the stored slot is used later.
  expected_gradient <- get_gradient(fit_with_optimization_big)
  # clear() frees C++ side state; this test confirms R-side cached values persist.
  clear()
  expect_equal(get_gradient(fit_with_optimization_big), expected_gradient)
})

test_that("get_estimates() handles missing parameter_id values", {
  #' @description Test get_estimates() path where parameter_id can be NA and unique IDs are backfilled.
  # Mock TMB-side output with repeated labels and missing parameter IDs.
  mock_tmb <- tibble::tibble(
    label = c("alpha", "alpha", "beta"),
    parameter_id = c(NA_real_, NA_real_, 3),
    uncertainty = c(0.1, 0.2, 0.3),
    log_like_cv = c(1, 2, 3),
    gradient = c(0.01, 0.02, 0.03)
  )
  # Mock JSON-side output with matching rows so the join path is exercised.
  mock_json <- tibble::tibble(
    label = c("alpha", "alpha", "beta"),
    parameter_id = c(NA_real_, NA_real_, 3),
    estimation_type = c("fixed_effects", "fixed_effects", "constant"),
    value = c(10, 20, 30)
  )

  # Mock only the expensive reshaping helpers to keep this a pure unit test.
  result <- testthat::with_mocked_bindings(
    {
      get_estimates(fit_with_optimization_big)
    },
    reshape_tmb_estimates = function(...) mock_tmb,
    reshape_json_estimates = function(...) mock_json,
    .package = "FIMS"
  )

  # unique_id is internal and should be removed before returning to users.
  expect_true(tibble::is_tibble(result))
  expect_true("uncertainty" %in% names(result))
  expect_false("unique_id" %in% names(result))
  expect_equal(nrow(result), 3)
})

## Edge handling ----
test_that("`is.FIMSFit()` returns correct outputs for edge cases", {
  #' @description Test that `is.FIMSFit("not_a_FIMSFit")` returns FALSE.
  expect_false(is.FIMSFit("not_a_FIMSFit"))

  # Modify the total time to be more than a day
  fit_with_optimization_big@timing[["time_total"]] <- 86401 # 60*60*24+1
  #' @description Test that `print(FIMSFit)` returns no error when the total time is more than a day.
  expect_no_error(print(fit_with_optimization_big))

  # Modify the total time to be more than a hour
  fit_with_optimization_big@timing[["time_total"]] <- 3601 # 60*60+1
  #' @description Test that `print(FIMSFit)` returns no error when the total time is more than an hour.
  expect_no_error(print(fit_with_optimization_big))

  # Modify the total time to be more than a minute
  fit_with_optimization_big@timing[["time_total"]] <- 61 # 60+1
  #' @description Test that `print(FIMSFit)` returns no error when the total time is more than a minute.
  expect_no_error(print(fit_with_optimization_big))
  
  #' @description Test that `fit_without_optimization_big` has a total time of 0 seconds.
  expect_equal(
    object = fit_without_optimization_big@timing[["time_total"]],
    expected = 0
  )

})

## Error handling ----
test_that("fit_fims() errors when optimization fails to converge", {
  # Create a simple test case that will fail to converge by setting
  # extremely restrictive iteration limits
  testthat::skip_if_not(
    testthat:::env_var_is_true("RUN_SLOW_TESTS"),
    message = "Skipping: RUN_SLOW_TESTS is not set to true."
  )

  # Skip if test fixtures don't exist
  skip_if_not(file.exists(testthat::test_path("fixtures", "integration_test_data.RData")))

  load(testthat::test_path("fixtures", "integration_test_data.RData"))

  # Set up the model with data
  parameters <- FIMS::parameters_big

  initialized_model <- parameters |>
    initialize_fims(data = data_big)

  # Set control parameters that will cause convergence failure
  # by making iteration limits extremely low
  bad_control <- list(
    eval.max = 1,
    iter.max = 1,
    trace = 0
  )

  #' @description Test that fit_fims() throws an informative warning when convergence fails.
  expect_warning(
    result <- initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control),
    regexp = "Optimization failed convergence checks"
  )

  # Set control parameters that will allow convergence but
  # return large gradient
  bad_control <- list(
    rel.tol = 0.1,
    trace = 0
  )

  #' @description Test that fit_fims() throws an informative error when max gradient is high.
  expect_warning(
    result <- initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control),
    regexp = "Maximum absolute gradient"
  )

  # Set control parameters that will allow convergence but
  # return moderately large gradient
  bad_control <- list(
    rel.tol = 1e-4,
    trace = 0
  )

  #' @description Test that fit_fims() throws an informative warning when max gradient is moderately high.
  expect_warning(
    result <- initialized_model |>
      fit_fims(optimize = TRUE, control = bad_control),
    regexp = "Optimization resulted in high gradients"
  )

  clear()

  # Fix Landings sd at high value in penalized likelihood model to cause high standard errors
  parameters_4_model <- parameters |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_devs",
        time = 2:get_n_years(data_big),
        estimation_type = "fixed_effects"
      ),
      by = c("label", "time")
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        module_name = "Recruitment",
        label = "log_sd",
        estimation_type = "constant"
      ),
      by = c("module_name", "label")
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        module_type = "Landings",
        label = "log_sd",
        time = 1:get_n_years(data_big),
        value = 10
      ),
      by = c("module_type", "label", "time")
    )

  initialized_model <- parameters_4_model |>
    initialize_fims(data = data_big)

  #' @description Test that fit_fims() throws an informative warning when parameter SE values are too large.
  expect_warning(
    result <- initialized_model |> fit_fims(optimize = TRUE),
    regexp = "Large condition number detected in Hessian"
  )

  clear()

  # Estimate the first (age, year) of natural mortality to cause NA standard errors
  parameters_4_model <- parameters |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_devs",
        time = 2:get_n_years(data_big),
        estimation_type = "fixed_effects"
      ),
      by = c("label", "time")
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        module_name = "Recruitment",
        label = "log_sd",
        estimation_type = "constant"
      ),
      by = c("module_name", "label")
    ) |>
    dplyr::rows_update(
      tibble::tibble(
        label = "log_M",
        time = 1,
        estimation_type = "fixed_effects"
      ),
      by = c("label", "time")
    )

  initialized_model <- parameters_4_model |>
    initialize_fims(data = data_big)

  #' @description Test that fit_fims() throws an informative warning when parameter SE values are NA.
  expect_warning(
    result <- initialized_model |> fit_fims(optimize = TRUE),
    regexp = "NA standard errors"
  )

  clear()

  # Add an additional slope parameter to make the model overparameterized
  parameters_4_model <- parameters |>
    dplyr::rows_update(
      tibble::tibble(
        fleet = "fleet1",
        label = "log_q",
        estimation_type = "fixed_effects"
      ),
      by = c("fleet", "label")
    )

  initialized_model <- parameters_4_model |>
    initialize_fims(data = data_big)

  #' @description Test that fit_fims() throws an informative warning when the Hessian is not positive definite.
  expect_warning(
    result <- initialized_model |> fit_fims(optimize = TRUE),
    regexp = "Standard error calculations failed convergence checks"
  )

  #' @description Test that fit_fims() returns a non-converged model when you know it is not supposed to converge. The warnings and messages are suppressed because {nlminb} uses backend code that we do not want to print to the screen during testing but we know will be there.
  # Create parameters
  initialized_poor_model <- create_default_configurations(data_big) |>
    create_default_parameters(data = data_big) |>
    tidyr::unnest(cols = data) |>
    dplyr::rows_update(
      tibble::tibble(
        module_name = "Population",
        label = c("log_init_naa"),
        age = 1,
        value = -Inf
      ),
      by = c("module_name", "label", "age")
    ) |>
    initialize_fims(data = data_big)
  test_results <- suppressWarnings(suppressMessages(
    fit_fims(initialized_poor_model, optimize = TRUE)
  ))
  expect_true(inherits(test_results, "FIMSFit"))
  expect_equal(get_opt(test_results)[["convergence"]], 1L)
  expect_equal(
    names(get_opt(test_results)),
    c("par", "objective", "convergence", "message")
  )

  clear()
})

test_that("try_nlminb() handles normal, soft-fail, and hard-fail paths", {
  #' @description Test try_nlminb() returns an optimizer object on success and NULL on failure paths.
  # Quadratic objective gives a stable optimizer success case.
  mock_object_ok <- list(
    fn = function(par) sum(par^2),
    gr = function(par) 2 * par
  )

  ok_result <- FIMS:::try_nlminb(
    object = mock_object_ok,
    control_list = list(trace = 0),
    starting_values = c(1, -1)
  )
  expect_type(ok_result, "list")
  expect_true(is.finite(ok_result[["objective"]]))

  # Non-finite objective should trigger soft-fail handling and return NULL.
  mock_object_inf <- list(
    fn = function(par) Inf,
    gr = function(par) rep(0, length(par))
  )
  expect_warning(
    inf_result <- FIMS:::try_nlminb(
      object = mock_object_inf,
      control_list = list(trace = 0),
      starting_values = c(0)
    ),
    regexp = "non-finite"
  )
  expect_null(inf_result)

  # Hard errors in fn should be caught by tryCatch and converted to NULL.
  mock_object_error <- list(
    fn = function(par) stop("forced failure"),
    gr = function(par) rep(0, length(par))
  )
  expect_no_error(
    error_result <- FIMS:::try_nlminb(
      object = mock_object_error,
      control_list = list(trace = 0),
      starting_values = c(0)
    )
  )
  expect_null(error_result)
})

test_that("return_failed_nlminb() returns standardized fallback structure", {
  #' @description Test return_failed_nlminb() returns timing and optimizer fields with non-converged status.
  # Minimal object shape required by the fallback helper.
  mock_object <- list(par = c(a = 1, b = 2))
  expect_warning(
    failed <- FIMS:::return_failed_nlminb(mock_object),
    regexp = "did not lead to a converged model"
  )

  expect_equal(names(failed), c("timing", "opt"))
  expect_equal(
    names(failed[["timing"]]),
    c("time_optimization", "time_sdreport", "time_total")
  )
  expect_equal(
    names(failed[["opt"]]),
    c("par", "objective", "convergence", "message")
  )
  # Convergence = 1L and objective = NA are the key failure markers.
  expect_equal(failed[["opt"]][["convergence"]], 1L)
  expect_true(is.na(failed[["opt"]][["objective"]]))
})
